import subprocess,time,sys,statistics,json,os
args=sys.argv[1:]
reps=int(os.getenv('REPS','5'))
path=os.getenv('INPUT','/data/measurements-dev.txt')
expected=open('/work/base.out','rb').read()
results={b:[] for b in args}
for rep in range(reps):
 for b in args if rep%2==0 else args[::-1]:
  t=time.perf_counter();p=subprocess.run([b,path],stdout=subprocess.PIPE,check=True);t=time.perf_counter()-t
  if p.stdout!=expected:raise Exception('WRONG '+b)
  results[b].append(t)
  print(f'{rep} {b}: {t:.6f}',flush=True)
for b,ts in results.items():print(b, 'median',statistics.median(ts),'min',min(ts),'all',ts,flush=True)

