#ifndef THREADS
#define THREADS 4
#endif
#ifndef STREAMS
#define STREAMS 3
#endif
struct alignas(16) Entry { int64_t sum=0; uint32_t count=0; int16_t lo=1000,hi=-1000; };
struct alignas(64) Table { Entry e[413]; };
static inline uint64_t load64(const char*p){uint64_t x;memcpy(&x,p,8);return x;}
static inline void one(const char*&p,Table&tab) {
 uint32_t k;memcpy(&k,p,4);Meta m=prefix[(k*PREFIX_MUL)>>PREFIX_SHIFT];
 unsigned id=m.id,len=m.len;
 if(!len){Variant v=variants[id+(unsigned char)p[m.pos]];id=v.id;len=v.len;if(len>=256){v=variants[id+(unsigned char)p[len-256]];id=v.id;len=v.len;}}
 p+=len+1;
 uint64_t w=load64(p);unsigned dot=__builtin_ctzll(~w & 0x10101000ull);
 int sign=(int64_t)(~w<<59)>>63;
 uint64_t digits=((w & ~(uint64_t(sign)&0xff)) << (28-dot)) & 0x0f000f0f00ull;
 int t=(digits*0x640a0001ull)>>32 & 1023;t=(t^sign)-sign;
 p+=(dot>>3)+3;
 auto&e=tab.e[id];e.sum+=t;++e.count;e.lo=std::min<int>(e.lo,t);e.hi=std::max<int>(e.hi,t);
}
static void process(const char* p,const char* end,Table& tab) {
 const char*ptr[STREAMS],*stop[STREAMS];ptr[0]=p;stop[STREAMS-1]=end;
 for(int i=1;i<STREAMS;++i){const char*q=p+(end-p)*i/STREAMS;while(q<end&&q>p&&q[-1]!='\n')++q;ptr[i]=q;stop[i-1]=q;}
 for(;;){bool done=false;for(int i=0;i<STREAMS;++i)done|=ptr[i]>=stop[i];if(done)break;for(int i=0;i<STREAMS;++i)one(ptr[i],tab);}
 for(int i=0;i<STREAMS;++i)while(ptr[i]<stop[i])one(ptr[i],tab);
}
static void number(long long t) { if(t<0){putchar('-');t=-t;}printf("%lld.%lld",t/10,t%10); }
int main(int argc,char**argv) {
