 const int nt=THREADS; std::vector<Table> tables(nt); std::vector<std::thread> threads;const char* bounds[nt+1]; bounds[0]=data;bounds[nt]=data+n;
 for(int i=1;i<nt;++i){const char*p=data+n*i/nt;while(p<data+n&&p>data&&p[-1]!='\n')++p;bounds[i]=p;}
 for(int i=1;i<nt;++i)threads.emplace_back(process,bounds[i],bounds[i+1],std::ref(tables[i]));process(bounds[0],bounds[1],tables[0]);for(auto&t:threads)t.join();
 for(int i=1;i<nt;++i)for(int j=0;j<413;++j){auto&e=tables[i].e[j];auto&r=tables[0].e[j];r.sum+=e.sum;r.count+=e.count;r.lo=std::min(r.lo,e.lo);r.hi=std::max(r.hi,e.hi);}
 putchar('{');bool first=true;for(int j=0;j<413;++j){auto&e=tables[0].e[j];if(!e.count)continue;if(!first)fputs(", ",stdout);first=false;fputs(names[j],stdout);putchar('=');number(e.lo);putchar('/');long long a=e.sum<0?-e.sum:e.sum;long long v=(a+e.count/2)/e.count;if(e.sum<0)v=-v;number(v);putchar('/');number(e.hi);}putchar('}');
